# Lesson 7: sweep at exit SMA = 5, annualised Sharpe, in-sample 2016-2020 vs out-of-sample 2021-2025, 5 bps
SWEEP_THR = [5, 10, 15, 20, 25, 30]
SWEEP_IS = [-0.0660, -0.1108, 0.0100, 0.3608, 0.3145, 0.3278]
SWEEP_OS = [0.8325, 0.6821, 0.7420, 0.8049, 0.8144, 0.7315]

# Capstone reference: fixed RSI(2)<10 / SMA5 at 10 bps, anchored three-fold walk-forward
FOLD_IS = [-0.3003, -0.0429, -0.0071]
FOLD_OS = [0.2017, 0.0943, 0.8103]


def research_loop():
    flow_diagram(HERE / "research-loop.svg",
                 ["Hypothesis", "Rule", "Test", "Decide", "Record"],
                 title="The research loop: the order is the discipline",
                 notes=["a market reason, written before any data is opened",
                        "entry, exit, size, execution convention, all in code",
                        "next-bar fills, costs, truncation check, out-of-sample",
                        "pass/fail against thresholds fixed in advance",
                        "log the result even when it fails; count the attempt"])


def equity_costs():
    line_chart(HERE / "rsi2-equity-costs.svg",
               {"0 bps/side": EQ_0BPS, "5 bps/side": EQ_5BPS, "10 bps/side": EQ_10BPS, "SPY buy-and-hold": EQ_SPY},
               title="RSI(2)<10 on SPY, exit above 5-day SMA, 2016-2025: growth of $1",
               y_label="growth of $1", x_labels=X, hlines=[(1.25, "T-bills (+25.1%)")])


def sweep_bars():
    labels, values, colors = [], [], []
    for thr, a, b in zip(SWEEP_THR, SWEEP_IS, SWEEP_OS):
        labels += [f"IS<{thr}", f"OOS<{thr}"]; values += [a, b]; colors += [COLORS[2], COLORS[1]]
    bar_chart(HERE / "sweep-is-vs-oos.svg", labels, values,
              title="RSI(2) entry threshold sweep, exit SMA5, 5 bps: in-sample (2016-20) vs out-of-sample (2021-25) Sharpe",
              y_label="annualised Sharpe", y_fmt=lambda v: f"{v:+.2f}", colors=colors)


def walk_forward():
    flow_diagram(HERE / "walk-forward-folds.svg",
                 ["Fold 1: train 2016-19, test 2020-21", "Fold 2: train 2016-21, test 2022-23", "Fold 3: train 2016-23, test 2024-25"],
                 title="Anchored walk-forward, three folds, 24-point grid re-fitted each fold (5 bps)",
                 notes=["picked RSI<30 / SMA20; train Sharpe 0.53, test 0.48",
                        "picked RSI<25 / SMA5; train Sharpe 0.56, test 0.25",
                        "picked RSI<25 / SMA5; train Sharpe 0.48, test 0.86"])


def drawdown():
    line_chart(HERE / "rsi2-drawdown.svg",
               {"RSI(2) rule, 5 bps": DD_5BPS, "SPY buy-and-hold": DD_SPY},
               title="Drawdown from running peak, month-end worst, 2016-2025",
               y_label="drawdown", x_labels=X, y_fmt=lambda v: f"{v*100:.0f}%",
               hlines=[(-0.20, "-20% gate")])


def gate_stack():
    flow_diagram(HERE / "gate-stack.svg",
                 ["G1 Data", "G2 Leakage", "G3 Costs", "G4 Out-of-sample", "G5 Portfolio", "G6 Paper"],
                 title="The gate stack: a rule trades only after every gate passes, in order",
                 notes=["rows verified, adjusted, point-in-time, no padding",
                        "truncation-invariant; next-bar fills only",
                        "positive at 10 bps/side and above cash",
                        "OOS Sharpe >= 0.5 and >= half of in-sample; DSR >= 0.95",
                        "corr < 0.5 with the book; max DD < 20%; capacity",
                        "60 sessions, fills reconciled, kill switch armed"])


def capstone_folds():
    labels, values, colors = [], [], []
    for i, (a, b) in enumerate(zip(FOLD_IS, FOLD_OS), 1):
        labels += [f"F{i} train", f"F{i} test"]; values += [a, b]; colors += [COLORS[2], COLORS[1]]
    bar_chart(HERE / "capstone-fold-sharpe.svg", labels, values,
              title="Capstone reference: RSI(2)<10 / SMA5 at 10 bps, anchored folds, annualised Sharpe",
              y_label="annualised Sharpe", y_fmt=lambda v: f"{v:+.2f}", colors=colors)


if __name__ == "__main__":
    for fn in (research_loop, equity_costs, sweep_bars, walk_forward, drawdown, gate_stack, capstone_folds):
        fn()
    print("wrote", sorted(p.name for p in HERE.glob("*.svg")))
